// Build full remediation context from all specialist results
const trigger = $input.first().json;

// Safe parse — the orchestrator passes JSON strings
const safeparse = (v) => { try { return typeof v === 'string' ? JSON.parse(v) : v; } catch { return v || {}; } };

const classification = safeparse(trigger.classification_result) || {};
const rca            = safeparse(trigger.rca_result)            || {};
const topology       = safeparse(trigger.topology_result)       || {};

const context = {
  incident: {
    incident_id:  trigger.incident_id,
    alarm_id:     trigger.alarm_id,
    device_name:  trigger.device_name,
    alarm_type:   trigger.alarm_type,
    severity:     trigger.severity,
    description:  trigger.description,
    timestamp:    trigger.alarm_timestamp,
  },
  classification: {
    alarm_category:    classification.alarm_category || 'Unknown',
    alarm_subtype:     classification.alarm_subtype  || trigger.alarm_type,
    severity:          classification.severity       || trigger.severity,
    is_service_affecting: classification.is_service_affecting ?? true,
    urgency:           classification.urgency        || 'Medium',
  },
  root_cause: {
    probable_root_cause:      rca.probable_root_cause      || 'Under investigation',
    root_cause_category:      rca.root_cause_category      || 'Unknown',
    confidence:               rca.confidence               || 0,
    requires_physical_inspection: rca.requires_physical_inspection ?? false,
    estimated_repair_time_hours:  rca.estimated_repair_time_hours || null,
    timeline_analysis:            rca.timeline_analysis || '',
    supporting_evidence:          rca.supporting_evidence || [],
    alternative_causes:           rca.alternative_causes  || [],
  },
  impact: {
    impact_level:               topology.impact_level        || 'Unknown',
    affected_nodes:             topology.affected_nodes      || [trigger.device_name],
    affected_services:          topology.affected_services   || [],
    traffic_rerouting_possible: topology.traffic_rerouting_possible ?? false,
    redundant_paths_available:  topology.redundant_paths_available  ?? false,
    estimated_customers_affected: topology.estimated_customers_affected || 0,
    cascade_risk:               topology.cascade_risk || '',
  },
  agent_started_at: new Date().toISOString(),
};

return [{ json: { context } }];

// Parse and validate Remediation Agent output
const raw         = $input.first().json;
const agentOutput = typeof raw.text === 'string' ? raw.text : (typeof raw.content === 'string' ? raw.content : '');
// chainLlm runs with onError=continue, so a failed LLM call arrives here as { error }
const llmError    = raw.error ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error)) : null;
const context     = $('Build Remediation Context').first().json.context;

let parsed;
try {
  if (llmError) throw new Error('LLM call failed: ' + llmError);
  const cleaned = agentOutput.replace(/```json?\n?/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    recommended_actions: [
      {
        priority: 1,
        action_type: 'Diagnostic',
        title: 'Manual investigation required',
        description: 'AI agent output could not be parsed. Manual NOC investigation is required.',
        estimated_duration_minutes: 30,
        requires_human_approval: true,
        cli_commands: [],
      }
    ],
    escalation_required: true,
    escalation_team: 'NOC',
    escalation_reason: 'AI analysis failed — manual review needed',
    preventive_measures: [],
    incident_report: `# Incident Report\n\n**Incident ID:** ${context.incident.incident_id}\n**Device:** ${context.incident.device_name}\n**Alarm:** ${context.incident.alarm_type}\n\n⚠️ Automated report generation failed. Manual investigation required.\n\n**Error:** ${e.message}`,
    report_generated_at: new Date().toISOString(),
    parse_error: e.message,
  };
}

// Validate structure
if (!Array.isArray(parsed.recommended_actions))  parsed.recommended_actions = [];
if (!Array.isArray(parsed.preventive_measures))  parsed.preventive_measures = [];
if (!parsed.report_generated_at) parsed.report_generated_at = new Date().toISOString();

// ── Command safety policy: strict allowlist of read-only commands ────────────
// Nothing here is ever executed — these are suggestions shown to a human — but anything
// that is not provably read-only is removed so it can't be copy-pasted onto a device.
const POLICY = 'read-only-allowlist-v1';
const ALLOWED_ACTION_TYPES = ['Diagnostic', 'Monitoring', 'Escalation', 'Documentation'];
const NO_CLI_ACTION_TYPES  = ['Escalation', 'Documentation'];   // people/process steps, not device commands
const MAX_ACTIONS = 10;
const MAX_COMMANDS_PER_ACTION = 5;

// verb -> allowed first topic word (show: Cisco/Juniper/Nokia/Ciena, display: Huawei)
const SHOW_TOPICS = [
  'interface', 'interfaces', 'ip', 'ipv6', 'bgp', 'ospf', 'isis', 'mpls', 'route', 'arp', 'lldp', 'cdp',
  'log', 'logging', 'version', 'inventory', 'environment', 'processes', 'memory', 'controllers',
  'optics', 'transceiver', 'transceivers', 'alarm', 'alarms', 'system', 'chassis', 'platform', 'hardware',
  'redundancy', 'ethernet', 'vlan', 'vlans', 'spanning-tree', 'ntp', 'clock', 'module', 'modules', 'card',
  'port', 'ports', 'lag', 'lacp', 'protection', 'aps', 'performance', 'pm', 'counters', 'statistics',
];
const ALLOWED = {
  show:    new Set(SHOW_TOPICS),
  display: new Set([...SHOW_TOPICS, 'logbuffer', 'trapbuffer', 'device', 'elabel', 'cpu-usage', 'memory-usage']),
};
// Rejected anywhere in a command, even after an allowed verb
const FORBIDDEN_WORDS = new Set([
  'configure', 'config', 'conf', 'commit', 'write', 'copy', 'delete', 'erase', 'reload', 'reboot', 'restart',
  'shutdown', 'no', 'clear', 'debug', 'undebug', 'set', 'unset', 'request', 'rollback', 'format', 'undo',
  'system-view', 'save', 'reset', 'install', 'upgrade', 'test', 'tech-support',
  // would print secrets (password hashes, keys, SNMP communities)
  'running-config', 'startup-config', 'configuration', 'current-configuration', 'saved-configuration',
]);
const CHAINING   = /[;|&`$<>\\\n\r'"(){}]/;          // chaining, pipes, redirection, substitution, quoting
const SAFE_CHARS = /^[A-Za-z0-9 ._:\/,-]+$/;
const EXTERNAL   = /(https?:|ftp:|mailto:|@|\b(email|e-mail|mail|sms|webhook|curl|wget|ssh|telnet|scp|sftp|api)\b)/i;

const checkCommand = (cmd) => {
  if (typeof cmd !== 'string') return 'not a string';
  const c = cmd.trim().replace(/\s+/g, ' ');
  if (!c) return 'empty command';
  if (c.length > 150) return 'too long';
  if (CHAINING.test(c)) return 'chained/redirected/substituted command';
  if (EXTERNAL.test(c)) return 'external action';
  if (!SAFE_CHARS.test(c)) return 'disallowed characters';
  const words = c.toLowerCase().split(' ');
  const bad = words.find(w => FORBIDDEN_WORDS.has(w));
  if (bad) return `forbidden keyword '${bad}'`;
  const [verb, topic] = words;
  if (!ALLOWED[verb]) return `unknown command '${verb}' (only show/display allowed)`;
  if (!topic || !ALLOWED[verb].has(topic)) return `'${verb} ${topic || ''}' is not on the read-only allowlist`;
  return null;
};

const rejectedCommands = [];
const rejectedActions  = [];
let allowedCount = 0;

parsed.recommended_actions = parsed.recommended_actions
  .filter(a => {
    if (!a || typeof a !== 'object') { rejectedActions.push({ title: null, reason: 'not an object' }); return false; }
    if (!ALLOWED_ACTION_TYPES.includes(a.action_type)) {
      rejectedActions.push({ title: a.title || null, reason: `action_type '${a.action_type}' not allowed` });
      return false;
    }
    return true;
  })
  .slice(0, MAX_ACTIONS)
  .map((a, i) => {
    const title = String(a.title || `Action ${i + 1}`).slice(0, 200);
    const cmds  = Array.isArray(a.cli_commands) ? a.cli_commands : [];
    const safe  = [];
    for (const cmd of cmds) {
      const reason = NO_CLI_ACTION_TYPES.includes(a.action_type)
        ? `${a.action_type} actions carry no device commands`
        : (safe.length >= MAX_COMMANDS_PER_ACTION ? 'too many commands for one action' : checkCommand(cmd));
      if (reason) rejectedCommands.push({ action: title, command: String(cmd).slice(0, 200), reason });
      else safe.push(cmd.trim().replace(/\s+/g, ' '));
    }
    allowedCount += safe.length;
    // Its whole purpose was an unsafe command: drop it so the description can't instruct one either
    if (cmds.length > 0 && safe.length === 0 && !NO_CLI_ACTION_TYPES.includes(a.action_type)) {
      rejectedActions.push({ title, reason: 'all suggested commands failed the read-only policy' });
      return null;
    }
    return {
      priority:                   Number.isInteger(a.priority) && a.priority > 0 ? a.priority : i + 1,
      action_type:                a.action_type,
      title,
      description:                String(a.description || '').slice(0, 1000),
      estimated_duration_minutes: Number.isFinite(a.estimated_duration_minutes) ? a.estimated_duration_minutes : null,
      cli_commands:               safe,
      requires_human_approval:    true,   // always enforced, regardless of LLM output
      auto_execute:               false,  // NetOpsAI never runs commands on devices
    };
  })
  .filter(Boolean);

if (parsed.recommended_actions.length === 0) {
  parsed.recommended_actions = [{
    priority: 1, action_type: 'Diagnostic', title: 'Manual investigation required',
    description: 'No AI-suggested action passed the read-only safety policy. Manual NOC investigation is required.',
    estimated_duration_minutes: 30, cli_commands: [], requires_human_approval: true, auto_execute: false,
  }];
}

parsed.command_validation = {
  policy:            POLICY,
  allowed_commands:  allowedCount,
  rejected_commands: rejectedCommands,
  rejected_actions:  rejectedActions,
};

const validTeams = ['NOC','Field Engineering','Vendor Support','Management','None'];
if (!validTeams.includes(parsed.escalation_team)) parsed.escalation_team = 'NOC';

return [{
  json: {
    ...parsed,
    alarm_id:     context.incident.alarm_id,
    incident_id:  context.incident.incident_id,
    agent_name:   'remediation_report',
    completed_at: new Date().toISOString(),
  }
}];
